args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?director ?directorLabel WHERE {
  {
    dbr:Apprentice_to_Murder dbo:director ?director .
  }
  UNION
  {
    dbr:Apprentice_to_Murder dbp:director ?director .
  }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = 'en') }
}

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?country ?countryLabel WHERE {
  {
    dbr:Ralph_L._Thomas dbo:nationality ?country .
    OPTIONAL { ?country rdfs:label ?countryLabel . FILTER(lang(?countryLabel) = 'en') }
  }
  UNION
  {
    dbr:Ralph_L._Thomas dbp:nationality ?country .
    OPTIONAL { ?country rdfs:label ?countryLabel . FILTER(lang(?countryLabel) = 'en') }
  }
  UNION
  {
    dbr:Ralph_L._Thomas dbo:birthPlace ?birthPlace .
    ?birthPlace dbo:country ?country .
    OPTIONAL { ?country rdfs:label ?countryLabel . FILTER(lang(?countryLabel) = 'en') }
  }
  UNION
  {
    dbr:Ralph_L._Thomas dbo:birthPlace ?birthPlace .
    ?birthPlace dbo:isPartOf ?country .
    OPTIONAL { ?country rdfs:label ?countryLabel . FILTER(lang(?countryLabel) = 'en') }
  }
  UNION
  {
    dbr:Ralph_L._Thomas dbo:birthPlace ?country .
    ?country a dbo:Country .
    OPTIONAL { ?country rdfs:label ?countryLabel . FILTER(lang(?countryLabel) = 'en') }
  }
}

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?country ?countryLabel WHERE {
  dbr:Apprentice_to_Murder dbo:director ?director .

  {
    ?director dbo:nationality ?country .
  }
  UNION
  {
    ?director dbp:nationality ?country .
  }
  UNION
  {
    ?director dbo:birthPlace ?birthPlace .
    {
      ?birthPlace dbo:country ?country .
    } UNION {
      ?birthPlace dbo:isPartOf ?country .
    } UNION {
      ?birthPlace a dbo:Country .
      BIND(?birthPlace AS ?country)
    }
  }

  FILTER(bound(?country))
  OPTIONAL { ?country rdfs:label ?countryLabel FILTER(lang(?countryLabel) = 'en') }
}

